pub mod auth;
pub mod db;
pub mod error;
pub mod matching;
pub mod state;

pub use state::AppState;

use axum::Router;
use tower_http::services::{ServeDir, ServeFile};
use std::path::Path;

pub mod api;

/// 构建完整应用：/api 下是 JSON 接口，其余路径交给前端静态资源（SPA）。
pub fn build_router(state: AppState) -> Router {
    let api = api::router();

    let static_dir = state.static_dir.clone();
    let app = Router::new().nest("/api", api);

    if Path::new(&static_dir).join("index.html").exists() {
        let serve = ServeDir::new(&static_dir)
            .not_found_service(ServeFile::new(Path::new(&static_dir).join("index.html")));
        app.fallback_service(serve).with_state(state)
    } else {
        // 测试或仅后端模式：没有前端构建产物时，未知路径返回 404 JSON
        app.fallback(|| async {
            (
                axum::http::StatusCode::NOT_FOUND,
                [("content-type", "application/json")],
                r#"{"error":"not found"}"#,
            )
        })
        .with_state(state)
    }
}

use sqlx::sqlite::{SqliteConnectOptions, SqlitePoolOptions};
use sqlx::SqlitePool;
use std::path::Path;
use std::str::FromStr;
use std::time::Duration;

/// 连接 SQLite：开启外键、WAL，并设置忙等——并发写事务（BEGIN IMMEDIATE）会排队而不是直接失败。
pub async fn connect(url: &str) -> anyhow::Result<SqlitePool> {
    // 支持传入文件路径或 sqlx URL
    let opts = if url.contains("://") {
        SqliteConnectOptions::from_str(url)?
    } else {
        if let Some(parent) = Path::new(url).parent() {
            if !parent.as_os_str().is_empty() {
                std::fs::create_dir_all(parent)?;
            }
        }
        SqliteConnectOptions::new().filename(url).create_if_missing(true)
    };

    let opts = opts
        .foreign_keys(true)
        .journal_mode(sqlx::sqlite::SqliteJournalMode::Wal)
        .busy_timeout(Duration::from_secs(10));

    let pool = SqlitePoolOptions::new()
        .max_connections(8)
        .connect_with(opts)
        .await?;
    Ok(pool)
}

const SCHEMA: &str = include_str!("../migrations/0001_init.sql");
const SEED: &str = include_str!("../migrations/seed.sql");

/// 建表（幂等）并在空库时写入演示数据。
pub async fn init(pool: &SqlitePool) -> anyhow::Result<()> {
    sqlx::raw_sql(SCHEMA).execute(pool).await?;

    let user_count: (i64,) = sqlx::query_as("SELECT COUNT(*) FROM users")
        .fetch_one(pool)
        .await?;
    if user_count.0 == 0 {
        sqlx::raw_sql(SEED).execute(pool).await?;
    }
    Ok(())
}

