pub fn recommend_model(height_cm: i64) -> &'static str {
    const BANDS: &[(i64, &str)] = &[
        (112, "10号"),
        (119, "9号"),
        (127, "8号"),
        (134, "7号"),
        (142, "6号"),
        (149, "5号"),
        (157, "4号"),
        (164, "3号"),
        (172, "2号"),
        (179, "1号"),
        (220, "0号"),
    ];
    for &(max, code) in BANDS {
        if height_cm <= max {
            return code;
        }
    }
    "0号"
}

