            .fetch_all(&state.pool)
            .await?
    } else {
        vec![]
    };

    let mut assets = Vec::new();
    for a in &rows {
        let at = active_transfer_of(&state.pool, &a.code).await?;
        let allocatable = a.status == "available" && at.is_none();
