        .collect();
    Ok(Json(json!({ "asset_code": code, "history": events })))
}

/// 标记损坏：仅限空闲桌椅（占用中的须先收回）。损坏品立即退出可分配池。
pub async fn mark_damaged(
    user: LogisticsUser,
    State(state): State<AppState>,
    Path(code): Path<String>,
) -> ApiResult<Json<Value>> {
