    }

    let mut tx = state.pool.begin().await?;
    sqlx::query("UPDATE assets SET status='damaged', updated_at=datetime('now') WHERE code=?")
        .bind(&code)
        .execute(&mut *tx)
        .await?;
    sqlx::query(
        "INSERT INTO asset_history (asset_code, event_type, actor_user_id, detail, created_at)
