use sqlx::sqlite::{SqliteConnectOptions, SqlitePoolOptions};
use sqlx::{SqliteConnection, SqlitePool};
use std::future::Future;
use std::path::Path;
use std::str::FromStr;
use std::time::Duration;

const SCHEMA: &str = include_str!("../migrations/0001_init.sql");
const SEED: &str = include_str!("../migrations/seed.sql");

/// 以 BEGIN IMMEDIATE 开启写事务：立刻获取 RESERVED 写锁，
/// 并发写请求在 busy_timeout 内排队，而不是各自持共享锁后升级死锁。
/// 这是“多人同时领用同一套桌椅只有一个成功”的关键：
/// 后来者排队进入事务后，条件 UPDATE 影响 0 行 → 返回 409。
pub async fn immediate<F, Fut, T, E>(pool: &SqlitePool, f: F) -> Result<T, E>
where
    F: FnOnce(&mut SqliteConnection) -> Fut,
    Fut: Future<Output = Result<T, E>>,
    E: From<sqlx::Error>,
{
    let mut conn = pool.acquire().await.map_err(E::from)?;
    sqlx::query("BEGIN IMMEDIATE")
        .execute(&mut conn)
        .await
        .map_err(E::from)?;
    match f(&mut conn).await {
        Ok(value) => {
            sqlx::query("COMMIT")
                .execute(&mut conn)
                .await
                .map_err(E::from)?;
            Ok(value)
        }
        Err(err) => {
            if let Err(rb) = sqlx::query("ROLLBACK").execute(&mut conn).await {
                tracing::error!("回滚失败: {rb}");
            }
            Err(err)
        }
    }
}

