        .bind(req.height_cm)
        .bind(sid)
        .execute(&mut *tx)
        .await?;

    if let Some((asset_code,)) = sqlx::query_as::<_, (String,)>(
        "SELECT code FROM assets WHERE assigned_student_id=?",
    )
    .bind(sid)
    .fetch_optional(&mut *tx)
