                "INSERT INTO asset_history (asset_code, event_type, from_class_id, to_class_id,
                                            to_student_id, actor_user_id, detail, created_at)
                 VALUES (?1,'assign',?2,?3,?4,?5,?6,datetime('now'))",
            )
            .bind(&code)
            .bind(location)
            .bind(class_id)
            .bind(sid)
            .bind(user.0.id)
