pub mod api;
pub mod auth;
pub mod db;
pub mod error;
pub mod matching;
pub mod state;

pub use state::AppState;

use axum::http::{header, StatusCode};
use axum::response::{IntoResponse, Response};
use axum::Router;
use tower_http::services::ServeDir;
use std::path::Path;

/// 构建完整应用：/api 下是 JSON 接口，其余路径交给前端静态资源（SPA）。
pub fn build_router(state: AppState) -> Router {
    let static_dir = state.static_dir.clone();
    let index_path = Path::new(&static_dir).join("index.html");
    let api = api::router();

    let app = Router::new().nest("/api", api);

    if index_path.exists() {
        let serve = ServeDir::new(&static_dir);
        app.fallback_service(serve)
            .fallback(move || spa_index(index_path.clone()))
            .with_state(state)
    } else {
        // 测试或仅后端模式：没有前端构建产物时，未知路径返回 404 JSON
        app.fallback(|| async {
            (
                StatusCode::NOT_FOUND,
                [(header::CONTENT_TYPE, "application/json")],
                r#"{"error":"not found"}"#,
            )
        })
        .with_state(state)
    }
}

/// SPA 回退：静态资源未命中时返回 index.html（200），由前端路由处理。
async fn spa_index(index_path: std::path::PathBuf) -> Response {
    match tokio::fs::read(&index_path).await {
        Ok(bytes) => (
            StatusCode::OK,
            [(header::CONTENT_TYPE, "text/html; charset=utf-8")],
            bytes,
        )
            .into_response(),
        Err(_) => (
            StatusCode::NOT_FOUND,
            [(header::CONTENT_TYPE, "application/json")],
            r#"{"error":"index.html missing"}"#,
        )
            .into_response(),
    }
}

